node --input-type=module <<'NODE'
const F = Math.fround;
const sum = terms => terms.reduce((a, b) => F(a + b), 0);
const weights = [F(0.5), F(0.5), 1];
const values = [1, F(0.6), F(0.1)];
const products = weights.map((w, j) => F(w * values[j]));
const l = sum(weights);
const inside = sum(products.map(p => F(p / l)));
const outside = F(sum(products) / l);
console.log({ inside, outside });
const j = [F(1), F(2 ** -24), F(2 ** -24)];
console.log({ sequential: sum(j), regrouped: F(j[0] + sum(j.slice(1))) });
