node --disable-warning=ExperimentalWarning --experimental-transform-types --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
registerHooks({ resolve(specifier, context, next) {
  try { return next(specifier, context); } catch (error) {
    if (error.code !== 'ERR_MODULE_NOT_FOUND' || !specifier.startsWith('.') || !specifier.endsWith('.js')) throw error;
    return next(specifier.slice(0, -3) + '.ts', context);
  }
}});
const { differential } = await import('./src/framework/contracts/differential.ts');
const { FiniteNumber } = await import('./src/framework/contracts/definitions.ts');
const { AnalysisManager } = await import('./src/framework/contracts/analysis-manager.ts');
const check = differential({
  id: 'probe.distance', version: '1', description: 'probe relation with a mixed comparator',
  inputs: { origin: FiniteNumber, output: FiniteNumber }, baseline: 'origin', subject: 'output', count: 1,
  cases: () => [0],
  run: (_side, value) => value,
  compare: (ref, actual) => Math.abs(ref - actual) <= 0.25
});
const mgr = new AnalysisManager();
for (const output of [1.125, 1.5]) {
  const verdict = await mgr.checkInvariant(check, { origin: 1, output });
  console.log(output, verdict.ok);
  if (verdict.ok !== (output === 1.125)) process.exitCode = 1;
}
