node --input-type=module <<'NODE'
const F = Math.fround;
const add = (a, b) => F(a + b);
const l = 3;
const values = [1, F(0.1), F(0.1)];
const inside = values.map(v => F(v / l)).reduce(add, 0);
const outside = F(values.reduce(add, 0) / l);
console.log({ inside, outside });
if (inside === outside) process.exitCode = 1;
