node --input-type=module <<'NODE'
const F = Math.fround;
const sum = terms => terms.reduce((a, b) => F(a + b), 0);
for (let k = 0; k <= 100; k++) {
  const values = [1, 1, F(k / 100)];
  const inside = sum(values.map(v => F(v / 3)));
  const outside = F(sum(values) / 3);
  if (inside !== outside) {
    console.log({ k, inside, outside });
    break;
  }
}
